package com.smartspend.dao;
import com.smartspend.model.Budget;import com.smartspend.util.DatabaseConnection;import java.sql.*;import java.util.*;
public class BudgetDAO { public List<Budget> findForMonth(int uid,int month,int year){List<Budget>a=new ArrayList<>();String q="SELECT b.*,c.name category_name,COALESCE((SELECT SUM(t.amount) FROM transactions t WHERE t.user_id=b.user_id AND t.category_id=b.category_id AND t.type='EXPENSE' AND YEAR(t.transaction_date)=b.year AND MONTH(t.transaction_date)=b.month),0) spent FROM budgets b JOIN categories c ON c.id=b.category_id WHERE b.user_id=? AND b.month=? AND b.year=? ORDER BY c.name";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,uid);p.setInt(2,month);p.setInt(3,year);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new Budget(r.getInt("id"),uid,r.getInt("category_id"),r.getDouble("amount"),month,year,r.getDouble("spent"),r.getString("category_name")));}}catch(SQLException e){throw new RuntimeException(e);}return a;}
 public void save(Budget b){String q="INSERT INTO budgets(user_id,category_id,amount,month,year) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,b.getUserId());p.setInt(2,b.getCategoryId());p.setDouble(3,b.getAmount());p.setInt(4,b.getMonth());p.setInt(5,b.getYear());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public void delete(int id,int uid){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM budgets WHERE id=? AND user_id=?")){p.setInt(1,id);p.setInt(2,uid);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
}
